import numpy as np,sys,itertools
L=open(sys.argv[1]).read().split('\n')
n=int(L[0]); sym=[];xyz=[]
for l in L[2:2+n]:
    p=l.split(); sym.append(p[0]); xyz.append([float(x) for x in p[1:4]])
xyz=np.array(xyz)
r={'H':0.31,'C':0.76,'N':0.71,'O':0.66,'F':0.57,'Cl':1.02,'Ge':1.20,'Au':1.36}
bonds={i:[] for i in range(n)}
mind=9
for i,j in itertools.combinations(range(n),2):
    d=np.linalg.norm(xyz[i]-xyz[j])
    if d<(r[sym[i]]+r[sym[j]])*1.3: bonds[i].append(j); bonds[j].append(i)
    mind=min(mind,d)
print('min dist',round(mind,2))
from collections import Counter
for i in range(n):
    print(i,sym[i],len(bonds[i]),[(j,sym[j]) for j in bonds[i]])
